(window.LP_CLIPS=window.LP_CLIPS||{});window.LP_CLIPS["ru"]=Object.assign(window.LP_CLIPS["ru"]||{},{"пип и безопасный переход": "", "енот пип проснулся в маленьком городке, и утро было ясным.": "", "пип хотел увидеть собаку, которая ждала на другой стороне дороги.": "", "но дорога была шумной, машины ехали быстро, а пип, кошка и утка были слишком малы, чтобы перейти.": "", "пип сел и задумался. люди построили эту дорогу, значит, люди могут её изменить.": "", "тогда пип постучал в двери, и соседи вышли послушать.": "", "вместе они попросили безопасное место для перехода, и город сказал да.": "", "приехали экскаваторы, прокатился каток, и рабочие нарисовали яркие полосы.": "", "теперь машины останавливаются, и все переходят вместе.": "", "пип обнял собаку. один тихий голос и несколько добрых друзей изменили улицу.": "", "мир создают люди, и люди могут сделать его добрее. спокойной ночи, пип. спокойной ночи всем.": ""});
